fn remove_duplicates(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0; // Return 0 for an empty array
    }

    let mut distinct_count = 1; // Start with the first element as distinct
    let mut last_seen = nums[0]; // The first element is the last seen distinct value

    for &num in &nums[1..] { // Iterate from the second element to the end
        if num != last_seen {
            distinct_count += 1; // Found a new distinct value
            last_seen = num; // Update the last seen distinct value
        }
    }

    distinct_count // Return the count of distinct values
}